document.querySelectorAll('nav details').forEach(detail=>detail.addEventListener('toggle',()=>{if(detail.open)document.querySelectorAll('nav details').forEach(other=>{if(other!==detail&&!other.contains(detail)&&!detail.contains(other))other.open=false})}));document.addEventListener('click',event=>{if(!event.target.closest('nav'))document.querySelectorAll('nav details').forEach(d=>d.open=false)});document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.querySelectorAll('nav details').forEach(d=>d.open=false);document.querySelector('#nav').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false')}});
const searchPages=[['Institutional Overview','about.html','About SVS and the institutional community'],['Medical College','medical.html','Medicine, campus and clinical learning'],['Dental College','dental.html','Dentistry and dental campus'],['Nursing College','nursing.html','Nursing, clinical labs and campus'],['Courses & Colleges','programmes.html','Academic disciplines and programme information'],['Research & Publications','research.html','Research information and public records'],['Leadership & Governance','leadership.html','Dean, Principal, faculty and leadership'],['Committees','committees.html','Committee and student support information'],['Student information','student-resources.html','Calendar, handbook, hostels and student support'],['Mandatory Disclosures & Approvals','disclosures.html','Faculty, approvals, seats, committees and public records'],['For Students','campus.html','Hostels, mess and campus guide'],['Photo Gallery','gallery.html','Real moments from SVS'],['Notices & Updates','notices.html','Admissions, academic and statutory information'],['Contact Us','contact.html','Contact information and admissions enquiries'],['Admissions','admissions.html','Prepare an admissions enquiry'],['MedCampusOS Portal','smart-portal.html','Proposed mobile experience and parent portal']];
document.querySelector('.site-search').addEventListener('click',()=>{show('','<label for="site-query">What are you looking for?</label><input id="site-query" class="site-search-input" type="search" placeholder="Programmes, faculty, hostels…"><div class="search-results" id="site-results" aria-live="polite"></div>','');dialog.classList.add('search-dialog');dialog.querySelector('.status')?.remove();dialog.querySelector('#dialog-content>h2')?.remove();const input=document.querySelector('#site-query');const render=()=>{const query=input.value.toLowerCase().trim();const matches=searchPages.filter(p=>p.join(' ').toLowerCase().includes(query));document.querySelector('#site-results').innerHTML=matches.length?matches.map(([title,url,description])=>`<a href="${url}">${title}<small>${description}</small></a>`).join(''):'<p class="search-empty">No matching pages. Try “nursing”, “admissions” or “faculty”.</p>';document.querySelectorAll('#site-results a').forEach(a=>a.addEventListener('click',()=>dialog.close()))};input.addEventListener('input',render);render();input.focus()});
const noticeContent={admissions:[['Information','Explore admissions at SVS','Prepare questions for your chosen institution.','admissions.html'],['Programmes','Medical, Dental & Nursing','Explore the institutional programme information centre.','programmes.html']],academic:[['Student resources','Academic documents & campus guide','Find the route to academic resources and campus facilities.','student-resources.html'],['Research','Research & publications','Access the research information and disclosure pathway.','research.html']],statutory:[['Public disclosures','Mandatory disclosures & approvals','Browse faculty, recognition and other statutory document categories.','disclosures.html'],['Governance','Committees & student support','Find the route to institutional committee information.','committees.html']]};
function renderNotices(key){const panel=document.querySelector('#notice-panel');if(!panel)return;panel.innerHTML=noticeContent[key].map(([type,title,text,url])=>`<a class="notice-item" href="${url}"><small>${type}</small><strong>${title}<span>↗</span></strong><p>${text}</p></a>`).join('')+'<p class="notice-footnote">Information links · Institution-approved announcements are awaiting publication.</p>';document.querySelectorAll('[data-notice]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.notice===key);b.setAttribute('aria-controls','notice-panel');b.tabIndex=b.dataset.notice===key?0:-1})}renderNotices('admissions');document.querySelectorAll('[data-notice]').forEach((b,i)=>{b.onclick=()=>renderNotices(b.dataset.notice);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const buttons=[...document.querySelectorAll('[data-notice]')],next=buttons[(i+(e.key==='ArrowRight'?1:2))%3];renderNotices(next.dataset.notice);next.focus()}}});

dialog.addEventListener('close',()=>dialog.classList.remove('search-dialog'));
